<form method="post" action="<?= site_url('tenant/admissions/programmes') ?>"><?= csrf_field() ?><label>Opening ID for update <input name="id" inputmode="numeric"></label><label>Cycle <select name="admission_cycle_id" required><?php foreach($cycles as $cycle): ?><option value="<?= esc($cycle['id']) ?>"><?= esc($cycle['title']) ?></option><?php endforeach ?></select></label><label>Programme <select name="programme_id" required><?php foreach($programmes as $programme): ?><option value="<?= esc($programme['id']) ?>"><?= esc($programme['name']) ?></option><?php endforeach ?></select></label><label>Department <select name="department_id" required><?php foreach($departments as $department): ?><option value="<?= esc($department['id']) ?>"><?= esc($department['name']) ?></option><?php endforeach ?></select></label><label>Entry level <select name="entry_level_id"><option value="">Not specified</option><?php foreach($levels as $level): ?><option value="<?= esc($level['id']) ?>"><?= esc($level['name']) ?></option><?php endforeach ?></select></label><label>Quota <input name="application_quota" inputmode="numeric"></label><label>Screening method <select name="screening_method"><option>manual_review</option><option>physical_screening</option><option>online_screening</option><option>exam</option><option>interview</option><option>combined</option></select></label><label>Status <select name="status"><option>open</option><option>closed</option><option>hidden</option><option>full</option><option>suspended</option></select></label><label>Requirement summary <textarea name="requirement_summary"></textarea></label><label>Instructions <textarea name="instructions"></textarea></label><button>Save programme opening</button></form>
